                mc.gameRenderer.clearPostProcessor();
            }
        } else if (!want.equals(cur) && (cur == null || AeroClient.MOD_ID.equals(cur.getNamespace()))) {
            ((GameRendererAccess) mc.gameRenderer).aero$setPostProcessor(want);
        }
    }
}
```

