      nodes.push(
        <strong className="font-medium text-gray-1000" key={match.index}>
          {match[2]}
        </strong>
      )
    }
    last = regex.lastIndex
  }
  if (last < text.length) nodes.push(text.slice(last))
  return <>{nodes}</>
}
```

